const row = $json;
const testId = String(row.ID || '').trim();
const inputText = String(row.Input_Text || '').trim();
const metaRaw = String(row.Input_Metadata_JSON || '').trim();

let task = '';
const re = /TASK:\s*([\s\S]*?)\s*SOLUTION:/g;
let m, last = null;
while ((m = re.exec(inputText)) !== null) last = m[1];
task = last ? last.trim() : inputText.replace(/^Schedule the meeting based on this:\s*/i, '');

let attendees = [];
const attRe = /schedule a meeting for ([^\.]+?) for/i;
const am = task.match(attRe);
if (am) {
  const namePart = am[1];
  const cleaned = namePart.replace(/ and /g, ', ');
  attendees = cleaned.split(',').map(s => s.trim()).filter(Boolean);
}

const today = new Date();
const yyyy = today.getFullYear();
const mm = String(today.getMonth() + 1).padStart(2, '0');
const dd = String(today.getDate()).padStart(2, '0');
const weekdays = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const todayWeekday = weekdays[today.getDay()];

function nextOccurrenceDate(weekday) {
  const targetIdx = weekdays.indexOf(weekday);
  if (targetIdx < 0) return null;
  const todayIdx = today.getDay();
  const daysUntil = (targetIdx - todayIdx + 7) % 7;
  const d = new Date(today);
  d.setDate(d.getDate() + daysUntil);
  const y = d.getFullYear();
  const mn = String(d.getMonth() + 1).padStart(2, '0');
  const dy = String(d.getDate()).padStart(2, '0');
  return y + '-' + mn + '-' + dy;
}

let taskWithDates = task;
weekdays.forEach(function(wd) {
  const wdRe = new RegExp('\\b' + wd + '\\b', 'g');
  if (wdRe.test(taskWithDates)) {
    const dateStr = nextOccurrenceDate(wd);
    if (dateStr) {
      taskWithDates = taskWithDates.replace(new RegExp('\\b' + wd + '\\b', 'g'), dateStr + ' (' + wd + ')');
    }
  }
});

const attendeeEmails = attendees.map(n => n.toLowerCase().replace(/[^a-z]/g, '') + '@example.com').join(', ');

const prompt = '[TEST_MODE] (test_id=' + testId + ') ' +
  'Today is ' + yyyy + '-' + mm + '-' + dd + ' (' + todayWeekday + '). The current year is ' + yyyy + '. ALL datetimes MUST use ' + yyyy + ' or later. NEVER use 2024 or any year from your training data.\n\n' +
  '*** SKIP THE AVAILABILITY CHECK ***\n' +
  'For this test the calendar will deliberately accumulate many overlapping TEST_ events across the 60 cases — that is expected and acceptable. DO NOT call GCal - Check Availability or GCal - List Events. Trust the constraints in the task below and create the event at the slot YOU compute from those constraints, even if the real calendar already has an overlapping event there. Overlaps are intentional.\n\n' +
  'Perform BOTH of the following actions in sequence:\n\n' +
  '1. CREATE the calendar event using GCal - Create Event with:\n' +
  '   - summary: "TEST_' + testId + ': Meeting with ' + attendees.join(', ') + '"\n' +
  '   - description: 2-3 lines noting the participants, the 30-minute duration, and test_id ' + testId + '.\n' +
  '   - start_iso / end_iso: the time you compute from the task constraints (ignore real-calendar conflicts).\n\n' +
  '2. CREATE a Gmail draft using Gmail - Create Draft (do NOT send) with:\n' +
  '   - sendTo: ' + attendeeEmails + '\n' +
  '   - subject: "TEST_' + testId + ': Meeting agenda confirmation"\n' +
  '   - message: a short agenda email confirming the slot you scheduled, listing attendees (' + attendees.join(', ') + '), including the chosen date and time, with 2-3 short agenda bullet points appropriate for a sync meeting.\n\n' +
  'Do not ask for confirmation — automated test mode.\n\n' +
  '*** CRITICAL: RESPECT EVERY CONSTRAINT STATED IN THE TASK ***\n' +
  'SKIPPING the live availability check does NOT mean you can ignore busy windows or rules stated in the task. The task text IS the source of truth for who is busy when and who refuses which times.\n' +
  'BEFORE choosing a slot, work through this internally:\n' +
  '  (a) List every busy window stated in the task (e.g. "Kenneth busy 10:00-11:30").\n' +
  '  (b) List every absolute restriction (e.g. "Sandra cannot meet on Monday before 13:00", "Jennifer cannot meet on Monday").\n' +
  '  (c) Pick a 30-min slot inside the stated working hours that violates NONE of (a) or (b). If multiple are valid, pick the earliest.\n' +
  'A slot that overlaps even ONE stated busy window, or violates even ONE stated rule, is WRONG and will fail the test. DO NOT propose such a slot. The constraint check is on YOU, not on the calendar tool.\n\n' +
  'IMPORTANT: All weekday names below have been pre-resolved to concrete future dates in ' + yyyy + '. Use those EXACT dates in your start_iso and end_iso parameters.\n\n' +
  '=== SCHEDULING TASK (skip live availability check; respect stated constraints; create at computed slot) ===\n' + taskWithDates;

return {
  json: {
    test_id: testId,
    subcategory: String(row.Subcategory || ''),
    channel: String(row.Channel || ''),
    golden_plan: metaRaw,
    attendees: attendees.join(', '),
    attendee_emails: attendeeEmails,
    started_at: new Date().toISOString(),
    message: { text: prompt, chat: { id: 'test_runner_cat4_' + testId } }
  }
};

const ids = $input.all().map(i => i.json.id).filter(Boolean);
const payload = $('Collect Cal Before').first().json;
return [{ json: Object.assign({}, payload, { draft_before_ids: ids }) }];

const agg = $input.first().json;
const payload = $('Collect Drafts Before').first().json;

const calBefore = new Set(payload.calendar_before_ids || []);
const draftBefore = new Set(payload.draft_before_ids || []);

// cal_after_events comes from Aggregate Cal After, embedded into Aggregate Drafts After flow
// because Aggregate Drafts After doesn't carry cal data forward, we read it from the upstream node directly
const calAfter = $('Aggregate Cal After').first()?.json?.cal_after_events || [];
const draftsAfter = agg.drafts_after || [];

const newEvents = calAfter.filter(e => e.id && !calBefore.has(e.id));
const newDrafts = draftsAfter.filter(d => d.id && !draftBefore.has(d.id));

const vaResp = $('Call Telegram VA').first()?.json || {};
const aiOutput = vaResp.ai_output || vaResp.output || '';

let ev = newEvents[0] || {};
let draftMeta = newDrafts[0] || {};

const startISO = (ev.start && (ev.start.dateTime || ev.start.date)) || '';
const endISO = (ev.end && (ev.end.dateTime || ev.end.date)) || '';
let day = '';
if (startISO) {
  const d = new Date(startISO);
  day = d.toLocaleDateString('en-US', { weekday: 'long', timeZone: 'Europe/Sarajevo' });
}

const startedAt = payload.started_at;
const elapsedMs = startedAt ? (Date.now() - new Date(startedAt).getTime()) : '';

let status = 'failed';
if (newEvents.length > 0 && newDrafts.length > 0) status = 'success';
else if (newEvents.length > 0 || newDrafts.length > 0) status = 'partial';

return [{ json: {
  test_id: payload.test_id,
  subcategory: payload.subcategory,
  channel: payload.channel,
  golden_plan: payload.golden_plan,
  attendees: payload.attendees,
  attendee_emails: payload.attendee_emails,
  calendar_event_id: ev.id || '',
  calendar_event_title: ev.summary || '',
  calendar_event_description: ev.description || '',
  calendar_event_start_iso: startISO,
  calendar_event_end_iso: endISO,
  calendar_event_day: day,
  draft_id: draftMeta.id || '',
  ai_output: String(aiOutput).slice(0, 800),
  new_event_count: newEvents.length,
  new_draft_count: newDrafts.length,
  response_time_ms: elapsedMs,
  status
}}];

const draft = $json;
const row = $('Diff: Find New Event + Draft').first().json;
const headers = draft.headers || {};
const subject = headers.subject || draft.subject || '';
const toAddr = headers.to || '';
let body = draft.text || draft.snippet || '';
if (!body && draft.payload) {
  body = draft.payload.snippet || '';
}
return { json: Object.assign({}, row, {
  draft_subject: subject,
  draft_to: toAddr,
  draft_message: String(body).slice(0, 2000)
})};

const drafts = $input.all().map(i => i.json);
const ids = drafts.map(d => d.id).filter(Boolean);
return [{ json: { drafts_after: drafts, drafts_after_ids: ids } }];

const ids = $input.all().map(i => i.json.id).filter(Boolean);
const payload = $('Build TEST_MODE Prompt').first().json;
return [{ json: Object.assign({}, payload, { calendar_before_ids: ids }) }];

const events = $input.all().map(i => i.json);
const ids = events.map(e => e.id).filter(Boolean);
return [{ json: { cal_after_events: events, cal_after_ids: ids } }];
